 private static void check(boolean value,String name){if(!value)throw new AssertionError(name);checks++;KingdomsMod.LOG.info("[integration PASS] {}",name);}
 private static final class CapturingConnection extends net.minecraft.network.Connection {
  final List<net.minecraft.network.protocol.Packet<?>> packets=new ArrayList<>();
  CapturingConnection(){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);}
  @Override public void send(net.minecraft.network.protocol.Packet<?> packet,io.netty.channel.ChannelFutureListener listener,boolean flush){packets.add(packet);}
 }
 private static com.mojang.brigadier.tree.RootCommandNode<net.minecraft.commands.CommandSourceStack> commandTree(net.minecraft.network.protocol.game.ClientboundCommandsPacket packet,net.minecraft.server.MinecraftServer server,ServerLevel level){
  return packet.getRoot(net.minecraft.commands.CommandBuildContext.simple(server.registryAccess(),level.enabledFeatures()),new net.minecraft.network.protocol.game.ClientboundCommandsPacket.NodeBuilder<net.minecraft.commands.CommandSourceStack>(){
   public com.mojang.brigadier.builder.ArgumentBuilder<net.minecraft.commands.CommandSourceStack,?> createLiteral(String id){return net.minecraft.commands.Commands.literal(id);}
   public com.mojang.brigadier.builder.ArgumentBuilder<net.minecraft.commands.CommandSourceStack,?> createArgument(String id,com.mojang.brigadier.arguments.ArgumentType<?> type,net.minecraft.resources.Identifier suggestion){return net.minecraft.commands.Commands.argument(id,type);}
   public com.mojang.brigadier.builder.ArgumentBuilder<net.minecraft.commands.CommandSourceStack,?> configure(com.mojang.brigadier.builder.ArgumentBuilder<net.minecraft.commands.CommandSourceStack,?> builder,boolean executable,boolean restricted){if(executable)builder.executes(c->1);return builder;}
  });
 }
 private static List<String> requestedSuggestions(net.minecraft.server.network.ServerGamePacketListenerImpl handler,CapturingConnection connection,String input){
  connection.packets.clear();handler.handleCustomCommandSuggestions(new net.minecraft.network.protocol.game.ServerboundCommandSuggestionPacket(7,input));
  var packet=(net.minecraft.network.protocol.game.ClientboundCommandSuggestionsPacket)connection.packets.getLast();
  return packet.suggestions().stream().map(net.minecraft.network.protocol.game.ClientboundCommandSuggestionsPacket.Entry::text).toList();
 }
 private static void commandVisibility(net.minecraft.server.MinecraftServer server,ServerLevel level,ServerPlayer player)throws Exception {
  var profile=new com.mojang.authlib.GameProfile(player.getUUID(),"TestMayor");var identity=new net.minecraft.server.players.NameAndId(player.getUUID(),"TestMayor");
  var connection=new CapturingConnection();var handler=new net.minecraft.server.network.ServerGamePacketListenerImpl(server,connection,player,net.minecraft.server.network.CommonListenerCookie.createInitial(profile,false));
  server.getPlayerList().op(identity,Optional.of(net.minecraft.server.permissions.LevelBasedPermissionSet.OWNER),Optional.empty());
  try{
   server.getCommands().sendCommands(player);var tree=commandTree((net.minecraft.network.protocol.game.ClientboundCommandsPacket)connection.packets.getLast(),server,level);
   check(tree.getChild("kingdom")!=null&&tree.getChild("kingdom").getCommand()!=null&&tree.getChild("kingdom").getChildren().isEmpty()&&tree.getChild("k")==null,"client command packet exposes only kingdom root and hides alias/subcommands");
   check(tree.getChild("kingdomadmin").getChild("clearcooldown")!=null&&tree.getChild("kingdomadmin").getChild("set").getChild("key")!=null,"admin command tree keeps its subcommands and argument nodes");
   check(server.getCommands().getDispatcher().execute("kingdom core",player.createCommandSourceStack())==1&&server.getCommands().getDispatcher().getRoot().getChild("kingdom").getChild("core")!=null,"hidden player subcommands still execute and open menus");
   var root=requestedSuggestions(handler,connection,"/k");check(root.contains("kingdom")&&root.contains("kingdomadmin")&&!root.contains("k"),"server root suggestions retain kingdom/admin and hide alias");
   check(requestedSuggestions(handler,connection,"/kingdom ").isEmpty(),"server player subcommand suggestions are empty");
   check(requestedSuggestions(handler,connection,"/kingdom flag auto").isEmpty(),"server player argument suggestions are empty");
   check(requestedSuggestions(handler,connection,"/k flag ").isEmpty(),"alias cannot expose hidden player suggestions");
   var admin=requestedSuggestions(handler,connection,"/kingdomadmin ");check(admin.contains("clearcooldown")&&admin.contains("set"),"admin subcommand suggestions remain available");
   check(requestedSuggestions(handler,connection,"/kingdomadmin set coreG").contains("coreGlow"),"admin config argument suggestions remain available");
   check(requestedSuggestions(handler,connection,"/time ").contains("query"),"unrelated vanilla command suggestions remain available");
  }finally{server.getPlayerList().deop(identity);}
  connection.packets.clear();server.getCommands().sendCommands(player);var tree=commandTree((net.minecraft.network.protocol.game.ClientboundCommandsPacket)connection.packets.getLast(),server,level);
  check(tree.getChild("kingdom")!=null&&tree.getChild("kingdomadmin")==null,"non-admin client tree retains kingdom and hides admin commands");
 }
