   journal.before=123;journal.after=124;recoveryStore.write("transaction.json",journal);rejected=false;try{new KingdomService(server,Path.of("recovery-fixture"),s.config);}catch(IllegalStateException expected){rejected=true;}check(rejected,"ambiguous interrupted transfer fails closed");recoveryStore.clearJournal();
